"""Generates ../schema.sql (MySQL DDL) from the SQLAlchemy models, so the two never drift apart.

Usage: python gen_schema.py
"""
from pathlib import Path

from sqlalchemy.dialects import mysql
from sqlalchemy.schema import CreateIndex, CreateTable

import app.models  # noqa: F401  (registers tables)
from app.database import Base

HEADER = """-- Attendance Pattern Analyzer - MySQL 8 schema
-- Generated by backend/gen_schema.py from the SQLAlchemy models.
-- Usage:  mysql -u root -p < schema.sql

CREATE DATABASE IF NOT EXISTS attendance_ai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE attendance_ai;

"""

out = [HEADER]
dialect = mysql.dialect()
for table in Base.metadata.sorted_tables:
    out.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";\n")
    for idx in table.indexes:
        out.append(str(CreateIndex(idx).compile(dialect=dialect)).strip() + ";")
    out.append("")

Path(__file__).resolve().parent.parent.joinpath("schema.sql").write_text("\n".join(out), encoding="utf-8")
print("schema.sql written with", len(Base.metadata.sorted_tables), "tables")
